<?php use Passport\Copy; ?>
<p class="eyebrow"><?= $e($t('MAKE THE PEOPLE VISIBLE')) ?></p><h1><?= $e($t('register')) ?></h1><p><?= $e($t('Record declared choices, not assumptions. Nothing is published until the final review.')) ?></p>
<form id="story-form" class="wizard card"><ol class="steps" aria-label="<?= $e($t('Registration steps')) ?>"><?php foreach (['Story','People','Terms','Shares','Review'] as $i => $step): ?><li data-step-label="<?= $i ?>"><?= $i + 1 ?> · <?= $e($t($step)) ?></li><?php endforeach ?></ol>
<section data-step="0"><h2><?= $e($t('1. Story and context')) ?></h2><div class="two"><label><?= $e($t('Title')) ?><input name="title" required maxlength="200"></label><label><?= $e($t('Language')) ?><input name="language" required maxlength="100" value="English"></label></div><div class="two"><label><?= $e($t('Creator type')) ?><select name="creatorType"><option value="PERSON"><?= $e($t('Person')) ?></option><option value="COMMUNITY"><?= $e($t('Community')) ?></option></select></label><label><?= $e($t('Creator or community name')) ?><input name="creatorName" required maxlength="200"></label></div><label><?= $e($t('Representative (required for a community)')) ?><input name="representativeName" maxlength="200"></label><div class="two"><label><?= $e($t('Media type')) ?><select name="mediaType"><option value="text"><?= $e($t('Text')) ?></option><option value="image"><?= $e($t('Image')) ?></option><option value="audio"><?= $e($t('Audio')) ?></option><option value="video"><?= $e($t('Video')) ?></option></select></label><label><?= $e($t('Visibility')) ?><select name="sensitivity"><option value="OPEN"><?= $e($t('Open passport')) ?></option><option value="RESTRICTED"><?= $e($t('Restricted · existence and steward only')) ?></option></select></label></div><label data-text-field><?= $e($t('Story text')) ?><textarea name="textBody" maxlength="100000" rows="7"></textarea></label><label data-file-field hidden><?= $e($t('Media file (up to 10 MB)')) ?><input name="media" type="file" accept="image/jpeg,image/png,image/webp,audio/mpeg,audio/wav,video/mp4,video/webm"></label><label><?= $e($t('Coarse place (optional; no precise location)')) ?><input name="placeCoarse" maxlength="100"></label><label><?= $e($t('Context from the steward')) ?><textarea name="contextNote" required maxlength="4000"></textarea></label></section>
<section data-step="1" hidden><h2><?= $e($t('2. Contributors and consent')) ?></h2><p><?= $e($t('Unchecked means not granted. Record each person’s choice for each purpose. For a community fund, record the representative’s declared choices.')) ?></p><div id="contributors"></div><button type="button" class="button secondary" id="add-person"><?= $e($t('Add contributor')) ?> +</button></section>
<section data-step="2" hidden><h2><?= $e($t('3. Declared terms')) ?></h2><label><?= $e($t('License preset (suggestion; confirm your choice)')) ?><select name="preset"><?php foreach (Copy::PRESETS as $value => $label): ?><option value="<?= $e($value) ?>"><?= $e($label) ?></option><?php endforeach ?></select></label><label class="check"><input type="checkbox" name="aiTrainingAllowed"> <?= $e($t('Declared terms allow AI training, subject to each contributor’s specific consent')) ?></label><label><?= $e($t('Public steward email')) ?><input name="contactEmail" type="email" required maxlength="254"></label><p class="muted"><?= $e($t('This contact address will be public, including for restricted stories. Use a suitable steward address.')) ?></p><label><?= $e($t('Additional declared terms (optional)')) ?><textarea name="notes" maxlength="2000"></textarea></label><label class="check"><input name="termsConfirmed" type="checkbox" required> <?= $e($t('I explicitly confirm these declared terms on behalf of the stewards.')) ?></label></section>
<section data-step="3" hidden><h2><?= $e($t('4. Revenue shares · demo calculator')) ?></h2><p><?= $e($t('Enter each share as a percentage, such as 70% and 30%. Shares must total 100%. Up to two decimal places are supported.')) ?></p><div id="shares"></div><label><?= $e($t('Sample demo amount (ZAR)')) ?><input name="sampleAmount" type="number" min="0" max="10000000" step="0.01" value="100"></label><div id="split-preview" role="status" aria-live="polite"></div><label class="check"><input name="sharesConfirmed" type="checkbox" required> <?= $e($t('I explicitly confirm the contributors and these revenue shares.')) ?></label></section>
<section data-step="4" hidden><h2><?= $e($t('5. Review and register')) ?></h2><div id="review"></div><p class="notice"><?= $e(Copy::LIMITS) ?></p><button class="button" type="submit"><?= $e($t('Register declared record')) ?> ↗</button></section><p class="form-message" role="status" aria-live="polite"></p><div class="wizard-nav"><button type="button" class="button secondary" id="previous"><?= $e($t('Back')) ?></button><button type="button" class="button" id="next"><?= $e($t('Continue')) ?> →</button></div></form>
<template id="person-template"><fieldset class="person"><legend><?= $e($t('Contributor')) ?></legend><div class="two"><label><?= $e($t('Name')) ?><input data-name required maxlength="200"></label><label><?= $e($t('Role')) ?><input data-role required maxlength="100"></label></div><label class="check"><input data-fund type="checkbox"> <?= $e($t('Community fund beneficiary')) ?></label><div class="consent-tags"><?php foreach (Copy::PURPOSES as $purpose => $label): ?><label class="check"><input type="checkbox" data-purpose="<?= $e($purpose) ?>"> <?= $e($label) ?></label><?php endforeach ?></div><button type="button" class="text-button" data-remove><?= $e($t('Remove contributor')) ?></button></fieldset></template>


